import sys
import asyncio
import time

from shiny import App, ui, render, reactive, Inputs, Outputs, Session
from shinywidgets import output_widget, render_widget
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import pandas as pd

# Detect Pyodide environment
def is_pyodide():
    try:
        import js  # type: ignore
        return True
    except ImportError:
        return False

# Fake psutil for Pyodide
if is_pyodide():
    import random
    class FakePsutil:
        @staticmethod
        def cpu_percent(interval=None):
            return random.uniform(0, 100)
    psutil = FakePsutil()
else:
    import psutil

# Hide axis ticks utility
def hide_ticks(ax):
    ax.set_xticks([])
    ax.set_yticks([])

# Available colormaps
COLORMAPS = sorted([
    "viridis", "plasma", "inferno", "magma", "cividis", "Greens", "Blues", "Reds", "Purples", "Oranges", "gray"
])

app_ui = ui.page_sidebar(
    ui.sidebar(
        ui.input_select("colormap", "Colormap", COLORMAPS, selected="viridis"),
        ui.input_action_button("clear", "Clear History"),
        ui.input_checkbox("freeze", "Freeze Output", False),
        ui.input_slider("nsamples", "Samples per Graph", 10, 100, 30),
        ui.input_slider("nrows", "Rows in Table", 5, 50, 10),
        width=300
    ),
    ui.layout_column_wrap(
        width=1/2,
        ui.card(
            ui.card_header("CPU Usage Graph"),
            ui.output_plot("cpu_plot", height="350px")
        ),
        ui.card(
            ui.card_header("CPU Usage Table"),
            ui.output_data_frame("cpu_table")
        )
    )
)

def server(input: Inputs, output: Outputs, session: Session):
    # Store CPU usage history
    cpu_history = reactive.Value([])

    @reactive.effect
    @reactive.periodic(1)
    def _update_cpu():
        if input.freeze():
            return
        usage = psutil.cpu_percent(interval=None)
        history = cpu_history()
        history.append({"time": time.strftime("%H:%M:%S"), "cpu": usage})
        # Keep only the last nsamples
        nsamples = input.nsamples()
        cpu_history(history[-nsamples:])

    @reactive.Effect
    @reactive.event(input.clear)
    def _clear_history():
        cpu_history([])

    @output
    @render.plot
    def cpu_plot():
        data = cpu_history()
        if not data:
            fig, ax = plt.subplots()
            ax.text(0.5, 0.5, "No data", ha="center", va="center")
            hide_ticks(ax)
            return fig
        df = pd.DataFrame(data)
        fig, ax = plt.subplots()
        cmap = input.colormap()
        ax.plot(df["time"], df["cpu"], marker="o", color=plt.get_cmap(cmap)(0.6))
        ax.set_ylim(0, 100)
        ax.set_ylabel("CPU Usage (%)")
        ax.set_xlabel("Time")
        ax.set_title("CPU Usage Over Time")
        hide_ticks(ax)
        fig.autofmt_xdate()
        return fig

    @output
    @render.data_frame
    def cpu_table():
        data = cpu_history()
        if not data:
            return pd.DataFrame(columns=["time", "cpu"])
        df = pd.DataFrame(data)
        nrows = input.nrows()
        return df.tail(nrows).iloc[::-1].reset_index(drop=True)

app = App(app_ui, server)
